import React from 'react';
// Assuming Tailwind CSS is set up in your project
// Assuming you are using React Router for <Link /> components
// import { Link } from 'react-router-dom';

// Placeholder Link component if React Router is not set up
// Replace with actual Link import if using React Router
// This placeholder assumes it might receive an onClick handler from a parent
const Link = ({ to, children, onClick, ...props }) => (
  <button onClick={() => onClick && onClick(to)} className="text-inherit hover:underline focus:outline-none" {...props}>
    {children}
  </button>
);


// Navbar component receives dark mode state, toggle function, and navigation handler as props
function Navbar({ darkMode, toggleDarkMode, onNavLinkClick, currentPage }) {
  return (
    // Navigation Bar container
    // Uses Tailwind classes for styling, responsiveness, and shadow
    // Background and text colors now respond to dark mode based on parent's 'dark' class
    <nav className="w-full bg-white dark:bg-gray-900 shadow-md dark:shadow-lg p-4 flex flex-col sm:flex-row justify-between items-center sticky top-0 z-10">
      {/* Site Title/Logo - Links to the homepage */}
      {/* Uses Tailwind classes for text styling and hover effects */}
      {/* Calls onNavLinkClick with 'home' */}
      <Link to="home" onClick={onNavLinkClick} className="text-xl font-bold text-blue-600 dark:text-blue-400 hover:text-blue-800 dark:hover:text-blue-300 transition-colors duration-200 mb-2 sm:mb-0">
        FB Downloader
      </Link>

      {/* Navigation Links and Dark Mode Toggle */}
      {/* Flex container for links, with spacing */}
      <div className="flex items-center space-x-4">
         {/* Example Nav Link - How It Works */}
         {/* Calls onNavLinkClick with 'how-to-use' */}
         <Link
           to="how-to-use"
           onClick={onNavLinkClick}
           className={`text-gray-700 dark:text-gray-300 hover:text-blue-600 dark:hover:text-blue-400 transition-colors duration-200 ${currentPage === 'how-to-use' ? 'font-semibold' : ''}`}
         >
           How to Use
         </Link>

        {/* Example Nav Link - FAQ */}
        {/* Calls onNavLinkClick with 'faq' */}
        {/*
        <Link
           to="faq"
           onClick={onNavLinkClick}
           className={`text-gray-700 dark:text-gray-300 hover:text-blue-600 dark:hover:text-blue-400 transition-colors duration-200 ${currentPage === 'faq' ? 'font-semibold' : ''}`}
        >
          FAQ
        </Link>
        */}


        {/* Dark Mode Toggle */}
        <button
          onClick={toggleDarkMode}
          className="p-2 rounded-full bg-gray-200 dark:bg-gray-700 text-gray-700 dark:text-gray-200 focus:outline-none focus:ring-2 focus:ring-blue-500 dark:focus:ring-blue-400 transition-colors duration-300"
          aria-label="Toggle Dark Mode"
        >
          {/* Simple icon representation (Sun for Light, Moon for Dark) */}
          {darkMode ? (
             // Sun icon for Dark Mode
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" />
            </svg>
          ) : (
            // Moon icon for Light Mode
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" />
            </svg>
          )}
        </button>

      </div>
    </nav>
  );
}

export default Navbar;
